/* Portable, source-backed inventory. It works over localhost and from index.html. */
'use strict';
const D=window.VOIDFALL_CONTENT;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roman=n=>typeof n==='number'?['','I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'][n]||n:n;
const svg=p=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`;
const icons={cards:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 1h7M1 8v10M9 9h6M9 13h6"/>',weapons:'<path d="m4 20 5-5m-3-4 7 7m-3-6L19 3l2 2-9 9M3 21l-1 1"/>',enemies:'<path d="M4 9 2 4l7 2 3-4 3 4 7-2-2 5v7l-8 6-8-6Z"/><circle cx="8" cy="12" r="1"/><circle cx="16" cy="12" r="1"/>',maps:'<path d="m2 5 7-3 6 3 7-3v17l-7 3-6-3-7 3Zm7-3v17M15 5v17"/>',decks:'<path d="m3 7 9-5 9 5-9 5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',assets:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 3-3 5 5"/>'};
const categories=[...new Set(D.cards.map(f=>f.category))];
icons.legacy='<path d="M3 12a9 9 0 1 0 2-6M3 3v6h6M12 7v5l3 3"/>';
const sections=[['cards','Cards',D.meta.counts.cards],['decks','Decks',categories.length],['weapons','Weapons',D.meta.counts.weapons],['enemies','Enemies',D.meta.counts.enemyForms+D.meta.counts.bosses],['maps','Maps',D.meta.counts.maps],['assets','Assets',D.meta.counts.images]];
sections.push(['legacy','Legacy Voidfall',window.VoidfallLegacy.count]);
document.querySelector('#navigation').innerHTML=sections.map(([id,label,count])=>`<a class="nav-item" href="#${id}">${svg(icons[id])}<span>${label}</span><span class="count">${count}</span></a>`).join('');
document.querySelector('#snapshot-date').textContent=new Date(D.meta.generatedAt).toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'});
document.querySelector('#revision').textContent=D.meta.revision;
let state={view:'cards',category:'Weapons',q:'',map:'all',faction:'black',limit:72,legacyKind:'Overview',legacyVersion:'all',legacyStatus:'All'};
const registry=new Map();
for(const f of [...D.cards,...D.weapons,...D.enemies]){for(const v of f.variants)registry.set(v.id,{v,f});if(f.evolution)registry.set(f.evolution.id,{v:f.evolution,f});}
for(const a of D.assets)registry.set(a.id,{v:a,f:{name:a.name,category:'Asset',accent:'#9eb8d8'}});
const art=v=>`<div class="art">${v.image?`<canvas data-art="${escapeHTML(state.faction==='white'&&v.whiteImage?v.whiteImage:v.image)}" aria-label="${escapeHTML(v.name)} artwork" role="img"></canvas>`:`<span class="glyph-art" aria-label="${escapeHTML(v.artNote||'Live card glyph')}">${v.rank==='EV'?'◇':'●'}</span>`}</div>`;
 const fmt=n=>typeof n==='number'?new Intl.NumberFormat('en',{maximumFractionDigits:2}).format(n):String(n);
const label=s=>s.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/Xp/g,'XP').replace(/Id/g,'ID');
function statPreview(v){return Object.entries(v.stats||{}).filter(([k,val])=>['Health','Speed','ContactDamage'].includes(k)&&val!==0).map(([k,val])=>`${k==='ContactDamage'?'Contact':k==='Health'?'HP':k} ${fmt(val)}`).join('\n');}
function tile(v,f){let enemy=D.enemies.includes(f);let content=enemy?statPreview(v):v.description;let singleLabel={'Wild cards':'WILD CARD','Rewards':'REWARD','Dealer':'DEALER OFFER','Repair':'REPAIR','Fragments':'FRAGMENT '+roman(v.rank)}[f.category];let rank=v.rank==='EV'?'EVOLUTION':singleLabel|| (enemy&&f.variants.length===1?f.category==='Bosses'?'BOSS':f.category==='Destroyers'?'INCIDENT':'ENEMY':(enemy?(f.presentation==='variants'?'FORM ':'TIER '):'RANK ')+roman(v.rank));return `<button class="tile ${v.rank==='EV'?'evolved':''}" style="--accent:${escapeHTML(v.accent||f.accent||'#71d7f7')}" data-id="${escapeHTML(v.id)}"><span class="tile-top"><span>${rank}</span><span class="tile-expand">↗</span></span>${art(v)}<h3>${escapeHTML(v.name).replaceAll('�','·')}</h3><p class="tile-description">${escapeHTML(content).split('\n').slice(0,3).join('\n')}</p><span class="tile-bottom">${v.rank==='EV'?'View requirements':enemy?escapeHTML(f.group):v.requirement?'Conditional':f.category==='Fragments'?'Permanent fragment':'Inspect card'} ↗</span></button>`;}
function matrix(families,{evolution=false,enemy=false,forms=false}={}){
 const columns=Math.max(...families.map(f=>f.variants.length),1),count=columns+Number(evolution);
 return `<div class="matrix" style="--columns:${count}" tabindex="0" role="region" aria-label="${enemy?'Enemy tier':'Card rank'} comparison. Scroll horizontally to see all columns."><div class="matrix-head"><span>FAMILY</span>${Array.from({length:columns},(_,i)=>`<span>${forms?'FORM':enemy?'TIER':'RANK'} ${roman(i+1)}</span>`).join('')}${evolution?'<span class="evolution-head">EVOLUTION</span>':''}</div>${families.map(f=>`<div class="matrix-row" style="--accent:${f.accent}"><div class="family-name">${f.icon?`<img class="small-art" src="${escapeHTML(f.icon)}" alt="">`:''}<h2>${escapeHTML(f.name).replaceAll('�','·')}</h2><p>${f.variants.length} ${enemy?(f.variants.length===1?'form':'forms'):(f.variants.length===1?'rank':'ranks')}${f.evolution&&evolution?' + evolution':''}</p><span class="pips">${f.variants.map(()=>'<i></i>').join('')}</span></div>${Array.from({length:columns},(_,i)=>f.variants[i]?tile(f.variants[i],f):'<div class="vacant" aria-label="No authored rank">—</div>').join('')}${evolution?(f.evolution?tile(f.evolution,f):'<div class="vacant" aria-label="No evolution">—</div>'):''}</div>`).join('')}</div>`;
}
const stats=items=>`<div class="stats-strip">${items.map(([n,l])=>`<div class="stat"><strong>${n}</strong><small>${l}</small></div>`).join('')}</div>`;
const search=placeholder=>`<label class="search">${svg('<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>')}<input type="search" aria-label="Search ${escapeHTML(state.view)}" placeholder="${placeholder}" value="${escapeHTML(state.q)}" id="search"></label>`;
const tabs=(items,selected)=>`<div class="tabs" aria-label="Categories">${items.map(([name,count])=>`<button class="tab ${name===selected?'active':''}" data-category="${escapeHTML(name)}" aria-pressed="${name===selected}">${escapeHTML(name)}${count!==undefined?` <small>${count}</small>`:''}</button>`).join('')}</div>`;
const matches=f=>!state.q||JSON.stringify(f).toLowerCase().includes(state.q.toLowerCase());
const empty=()=>'<div class="empty"><h2>No matching content</h2><p>Try another name, category or map.</p></div>';
const note=(name,count,tail='Click a card to inspect · scroll right for more ranks')=>`<div class="section-note"><span><strong>${escapeHTML(name)}</strong> / ${count} families</span><span>${tail}</span></div>`;
function cards(){
 const visible=D.cards.filter(f=>(state.category==='All cards'||f.category===state.category)&&matches(f));
 const fam=state.category==='All cards'?visible.filter(f=>f.category!=='Evolutions').map(f=>f.category==='Weapons'?D.weapons.find(w=>w.id===f.id):f):visible.map(f=>f.category==='Weapons'?D.weapons.find(w=>w.id===f.id):f);
 const strip=stats([[D.meta.counts.automaticWeapons,'Automatic weapons'],[D.meta.counts.supports,'Support families'],[D.meta.counts.evolutions,'Evolutions'],[D.cards.filter(f=>f.category==='Wild cards').length,'Wild cards'],[D.cards.filter(f=>f.category==='Late upgrades').reduce((n,f)=>n+f.variants.length,0),'Late upgrade ranks']]);
 const primary=['Weapons','Supports','Evolutions','Wild cards'];
 const other=['All cards',...categories.filter(c=>!primary.includes(c))];
 const ranked=['Weapons','Supports','Late upgrades','Workshop'];
 const display=(fs,cat)=>ranked.includes(cat)?matrix(fs,{evolution:cat==='Weapons'}):`<div class="grid">${fs.map(f=>tile(f.variants[0],f)).join('')}</div>`;
 const body=state.category==='All cards'?categories.filter(c=>c!=='Evolutions').map(c=>{const fs=fam.filter(f=>f.category===c);return fs.length?`<div class="subheading"><h2>${c}</h2><small>${fs.length} families</small></div>`+display(fs,c):''}).join(''):display(fam,state.category);
 return strip+`<div class="tools"><div class="pool-controls">${tabs(primary.map(c=>[c,D.cards.filter(f=>f.category===c).reduce((n,f)=>n+f.variants.length,0)]),state.category)}<select class="selector" id="pool-select" aria-label="Other card pools"><option value="" ${primary.includes(state.category)?'selected':''} disabled>More pools</option>${other.map(c=>`<option value="${c}" ${state.category===c?'selected':''}>${c}</option>`).join('')}</select></div>${search('Search cards…')}</div>`+note(state.category,visible.length)+(fam.length?body:empty());
}
function weapons(){
 const visible=D.weapons.filter(f=>(state.category==='All weapons'||(state.category==='Automatic'?f.category==='Weapons':f.category==='Legendary'))&&matches(f));
 return stats([[10,'Automatic weapons'],[2,'Manual legendaries'],[60,'Automatic ranks'],[10,'Weapon evolutions'],[6,'Legendary fragments']])+`<div class="tools">${tabs([['All weapons',12],['Automatic',10],['Legendary',2]],state.category)}${search('Search weapons…')}</div>`+note('Arsenal',visible.length)+(visible.length?matrix(visible,{evolution:visible.some(f=>f.evolution)}):empty());
}
const deckDescriptions={Weapons:'Ten automatic weapons, six ranks each. Evolutions pair a rank VI weapon with its maxed support.',Supports:'Shared and conditional support upgrades, including weapon-specific Split Shot.',Evolutions:'Ten weapon and support pairings that transform a completed weapon.', 'Late upgrades':'Output Tuning, Cooling Pass and Frame Patch after core progression is complete.', 'Wild cards':'Five unique rule-changing cards awarded by Roulette. Each appears at most once per run.',Repair:'Field Repair is a conditional level-up offer that restores 35 integrity.',Dealer:'Run upgrades plus legendary equip and upgrade offers. Each costs 100 run Scraps.',Fragments:'Six distinct permanent pieces assemble Sound Blade and Charged Rifle.',Rewards:'Scraps payouts, conditional fallbacks and the Random Power-Up Drop reveal.',Workshop:'Eight permanent upgrades with their rank costs and authored cosmetic layers. Separate from run offers.'};
function decks(){return `<div class="notice">${escapeHTML(D.meta.deckNote)}</div><div class="grid">${categories.map(c=>{const fs=D.cards.filter(f=>f.category===c);return `<button class="deck-card" data-deck="${c}" style="--accent:${fs[0].accent}"><span class="eyebrow">${fs.length} FAMILIES</span><div class="deck-amount">${fs.reduce((n,f)=>n+f.variants.length,0)}<span style="font-size:14px;color:var(--muted);margin-left:8px">cards</span></div><h2>${c} ↗</h2><p>${deckDescriptions[c]}</p></button>`}).join('')}</div>`;}
function enemies(){
 let fs=D.enemies.filter(f=>(state.category==='All enemies'||f.category===state.category)&&(state.map==='all'||f.maps.includes(state.map))&&matches(f));
 const cats=['All enemies','Shared roster','Elites','Court','Hydra','Null City','Destroyers','Bosses'];
 const tools=`<div class="tools">${tabs(cats.map(c=>[c]),state.category)}${search('Search enemies…')}<select class="selector" aria-label="Filter by map" id="map-select"><option value="all">All maps</option>${D.maps.map(m=>`<option value="${m.id}" ${state.map===m.id?'selected':''}>${m.name}</option>`).join('')}</select><div class="faction-toggle" aria-label="Court artwork faction"><button data-faction="black" class="${state.faction==='black'?'active':''}" aria-pressed="${state.faction==='black'}">Black army</button><button data-faction="white" class="${state.faction==='white'?'active':''}" aria-pressed="${state.faction==='white'}">White army</button></div></div>`;
 const groups=[...new Set(fs.map(f=>f.group))];
 return stats([[D.meta.counts.enemyFamilies,'Enemy families'],[D.meta.counts.enemyForms,'Enemy forms'],[D.meta.counts.bosses,'Bosses'],[14,'Shared tier families'],[8,'Maps']])+tools+`<div class="notice">${escapeHTML(D.meta.statNote)}</div>`+(fs.length?groups.map(g=>{const group=fs.filter(f=>f.group===g),ranked=group.filter(f=>f.variants.length>1&&f.presentation!=="variants"),single=group.filter(f=>f.variants.length===1),forms=group.filter(f=>f.presentation==="variants");return `<div class="subheading"><h2>${escapeHTML(g)}</h2><small>${group.length} families · ${group.reduce((n,f)=>n+f.variants.length,0)} forms</small></div>${ranked.length?matrix(ranked,{enemy:true}):''}${forms.length?'<div class="subheading"><h2>Sentinel forms</h2></div>'+matrix(forms,{enemy:true,forms:true}):''}${single.length?`<div class="grid" style="margin-top:18px">${single.map(f=>tile(f.variants[0],f)).join('')}</div>`:''}`}).join(''):empty());
}
function maps(){const ms=D.maps.filter(matches);return stats([[8,'Prepared maps'],[6,'Visits per route'],[4,'Shared bosses'],[4,'Arena-exclusive bosses']])+`<div class="tools">${search('Search maps…')}</div><div class="grid">${ms.map(m=>{const mobs=D.enemies.filter(e=>m.enemies.includes(e.id)),bosses=mobs.filter(e=>e.category==='Bosses');return `<button class="map-card" data-map="${m.id}"><img class="map-image" src="${m.image}" alt="${m.name} route thumbnail"><div class="map-body"><h2>${m.name}</h2><p>${escapeHTML(m.Description)}</p><small>${mobs.filter(e=>e.category!=='Bosses').length} roster groups · ${bosses.length} bosses ↗</small></div></button>`}).join('')}</div><div class="subheading"><h2>Zack's forms</h2><small>Same eye · three starting loadouts</small></div><div class="grid">${D.forms.map(f=>`<button class="deck-card" data-form="${f.Id}" style="--accent:#71d7f7"><h2>${f.Name}</h2><div class="deck-amount">${f.MaxHealth}<span style="font-size:14px;margin-left:8px;color:var(--muted)">HP</span></div><p>${escapeHTML(f.Blurb)}</p></button>`).join('')}</div>`;}
function assets(){const fs=D.assets.filter(a=>a.type!=='TTF'&&(state.category==='All artwork'||a.area===state.category)&&matches(a));return stats([[D.meta.counts.images,'Image assets'],[D.assets.filter(a=>a.area==='Generated'&&a.type!=='TTF').length,'Baked assets'],[D.assets.filter(a=>a.area==='Resources'&&a.type!=='TTF').length,'Resource images'],[D.assets.filter(a=>a.area==='Art').length,'Authored art']])+`<div class="tools">${tabs(['All artwork','Generated','Resources','Art'].map(c=>[c]),state.category)}${search('Search filenames or paths…')}</div><div class="section-note"><span>${Math.min(fs.length,state.limit)} of ${fs.length} assets</span><span>Includes animation frames, atlases and stored variants</span></div><div class="grid">${fs.slice(0,state.limit).map(a=>`<button class="tile asset-tile" data-id="${escapeHTML(a.id)}" style="--accent:#a9c1e4">${art(a)}<h3>${escapeHTML(a.name)}</h3><small>${a.size?a.size.join(' × ')+' · ':''}${a.area}</small></button>`).join('')}</div>${fs.length>state.limit?'<button class="more-button" id="load-more">Load more artwork</button>':''}`;}
const subtitles={legacy:'Five early versions. A clear view of what survived.',cards:'Every family. Every rank. One place.',weapons:'The complete arsenal, from first rank to evolution.',enemies:'The inhabitants of the Void, organized by roster and map.',maps:'Eight prepared arenas and their content.',decks:'The card pools that power a run.',assets:'Original artwork, animation frames and baked variants.'};
function render(){const section=sections.find(s=>s[0]===state.view);document.querySelector('h1').textContent=section[1];document.querySelector('.page-heading p').textContent=subtitles[state.view];document.querySelector('#crumb').textContent=section[1];document.querySelectorAll('.nav-item').forEach(a=>{const active=a.hash==='#'+state.view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('#summary').textContent=state.view==='legacy'?`${window.VOIDFALL_LEGACY.counts.contentFamilies} identities · v1–v5`:state.view==='cards'?`${D.meta.counts.cards} cards · ${D.meta.counts.cardFamilies} families`:state.view==='enemies'?`${D.meta.counts.enemyForms} forms · ${D.meta.counts.bosses} bosses`:state.view==='weapons'?'10 automatic · 2 legendary':state.view==='assets'?`${D.meta.counts.images} original images`:state.view==='maps'?'8 maps · 3 player forms':`${categories.length} card pools`;
 const views={cards,weapons,enemies,maps,decks,assets,legacy:()=>window.VoidfallLegacy.render(state)};document.querySelector('#content').innerHTML=views[state.view]();paintArt();}
function readHash(){const [view,params='']=location.hash.slice(1).split('?');state.view=sections.some(s=>s[0]===view)?view:'cards';const p=new URLSearchParams(params);const defaults={cards:'Weapons',weapons:'All weapons',enemies:'All enemies',assets:'All artwork'};state.category=p.get('category')||defaults[state.view]||'';state.q=p.get('q')||'';state.map=p.get('map')||'all';state.limit=72;if(state.view==='legacy'){state.legacyKind=p.get('kind')||'Overview';state.legacyVersion=p.get('version')||'all';state.legacyStatus=p.get('status')||'All'}render();}
function navigate(view,parameters={}){const q=new URLSearchParams(parameters).toString();location.hash=view+(q?'?'+q:'');}
function details(v,f){const dialog=document.querySelector('#details');dialog.classList.remove('legacy-dialog');let statsHTML='';if(v.stats)statsHTML=`<h3>${D.enemies.includes(f)?'Base stats':'Stats'}</h3><table class="stat-table">${Object.entries(v.stats).filter(([k,val])=>val!==null&&typeof val!=='object').map(([k,val])=>`<tr><td>${escapeHTML(label(k))}</td><td>${escapeHTML(fmt(val))}</td></tr>`).join('')}</table>`;const paths=[v.source||f.source,...(v.additionalSources||[])].filter(Boolean);const originalArt=D.assets.find(a=>a.image===v.image);if(originalArt)paths.push(originalArt.source);document.querySelector('#detail-content').innerHTML=`<div class="detail-hero" style="--accent:${v.accent||f.accent||'#71d7f7'}">${art(v)}<div class="eyebrow">${escapeHTML(f.category)}${v.rank?' / '+(v.rank==='EV'?'EVOLUTION':'RANK '+roman(v.rank)):''}</div><h2 id="detail-title">${escapeHTML(v.name||f.name).replaceAll('�','·')}</h2></div><div class="detail-body">${v.description?`<p>${escapeHTML(v.description)}</p>`:''}${v.requirement?`<h3>Requirement</h3><p>${escapeHTML(v.requirement)}</p>`:''}${statsHTML}${f.attacks?`<h3>Attacks</h3><table class="stat-table">${f.attacks.map(a=>`<tr><td>${escapeHTML(a.Id)}</td><td>${a.Damage} damage</td></tr>`).join('')}</table>`:''}${D.enemies.includes(f)?`<p class="art-note">${escapeHTML(D.meta.statNote)}</p>`:''}${v.size?`<h3>Asset</h3><table class="stat-table"><tr><td>Dimensions</td><td>${v.size.join(' × ')}</td></tr><tr><td>File size</td><td>${fmt(v.bytes/1024)} KB</td></tr><tr><td>Type</td><td>${v.type}</td></tr></table>`:''}${v.guid?`<p class="art-note">GUID ${v.guid}</p>`:''}${v.artNote?`<p class="art-note">${escapeHTML(v.artNote)}</p>`:''}<h3>Source</h3>${paths.map(s=>`<span class="source-path">${escapeHTML(s.path)}:${s.line}</span>`).join('')}<h3>Stable ID</h3><span class="source-path">${escapeHTML(v.id||f.id)}</span></div>`;dialog.showModal();dialog.scrollTop=0;paintArt(dialog);}
document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;if(el.dataset.legacyKind){state.legacyKind=el.dataset.legacyKind;state.limit=72;state.q='';render()}if(el.dataset.legacyStatus){state.legacyStatus=el.dataset.legacyStatus;state.limit=72;render()}if(el.dataset.legacyVersion){state.legacyVersion=el.dataset.legacyVersion;state.legacyKind='All content';state.legacyStatus='All';state.limit=72;render()}if(el.dataset.legacy)window.VoidfallLegacy.details(el.dataset.legacy,state);if(el.matches('.close-detail'))document.querySelector('#details').close();if(el.dataset.id){const item=registry.get(el.dataset.id);if(item)details(item.v,item.f)}if(el.dataset.category){state.category=el.dataset.category;state.limit=72;render()}if(el.dataset.deck)navigate('cards',{category:el.dataset.deck});if(el.dataset.map)navigate('enemies',{map:el.dataset.map});if(el.dataset.faction){state.faction=el.dataset.faction;render()}if(el.id==='load-more'){state.limit+=72;render()}if(el.dataset.form){const f=D.forms.find(x=>x.Id===el.dataset.form);details({id:f.Id,name:f.Name,description:f.Blurb+'\n\n'+(f.UnlockHint||'Available from the start.'),stats:{MaxHealth:f.MaxHealth,MoveSpeedMultiplier:f.MoveSpeedMultiplier,StartingWeapon:f.StartingWeapon},source:{path:'Assets/VoidFall/Content/PlayerForms.cs',line:1}},{category:'Player form',accent:'#71d7f7'})}});
document.addEventListener('input',event=>{if(event.target.id!=='search')return;const pos=event.target.selectionStart;state.q=event.target.value;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)});
document.addEventListener('change',event=>{if(event.target.id==='legacy-kind'){state.legacyKind=event.target.value;state.limit=72;state.q='';render()}if(event.target.id==='legacy-version'){state.legacyVersion=event.target.value;state.limit=72;render()}if(event.target.id==='map-select'){state.map=event.target.value;render()}if(event.target.id==='pool-select'){state.category=event.target.value;render()}});
document.querySelector('#details').addEventListener('click',event=>{if(event.target===event.currentTarget)event.currentTarget.close()});
window.addEventListener('hashchange',()=>{document.querySelector('#details').close();readHash();window.scrollTo(0,0)});
const artCache=new Map();
async function loadArt(url){
 if(artCache.has(url))return artCache.get(url);
 const pending=new Promise(resolve=>{const img=new Image();img.onload=()=>{
  // File URLs can taint pixel reads; still show the exact original image offline.
  if(location.protocol==='file:'){resolve({img,bounds:[0,0,img.width,img.height]});return;}
  const c=document.createElement('canvas');const scanScale=Math.min(1,256/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*scanScale));c.height=Math.max(1,Math.round(img.height*scanScale));
  const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(img,0,0,c.width,c.height);const px=cx.getImageData(0,0,c.width,c.height).data;let x0=c.width,y0=c.height,x1=0,y1=0;
  for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++){let i=(y*c.width+x)*4;if(px[i+3]>20&&Math.max(px[i],px[i+1],px[i+2])>22){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y)}}
  resolve({img,bounds:x1>x0?[x0/scanScale,y0/scanScale,(x1-x0+1)/scanScale,(y1-y0+1)/scanScale]:[0,0,img.width,img.height]});
 };img.onerror=()=>resolve(null);img.src=url});artCache.set(url,pending);return pending;
}
function paintArt(root=document){root.querySelectorAll('canvas[data-art]').forEach(async c=>{const a=await loadArt(c.dataset.art);if(!a||!c.isConnected)return;c.width=420;c.height=230;const ctx=c.getContext('2d');const [x,y,w,h]=a.bounds;const scale=Math.min(350/w,185/h);ctx.drawImage(a.img,x,y,w,h,(420-w*scale)/2,(230-h*scale)/2,w*scale,h*scale)})}
readHash();
